-- Original Linh Thu Ky sprite: 64px canvas, fixed ground y52, light upper-left.
-- Layered source and animation are generated by the Aseprite scripting API.
local spr = Sprite(64, 64, ColorMode.RGB)
local root = '/Users/nguyenhoangdacdat/dev/nguthu-unity-demo/ArtDirection/Handmade/SpiritTurtle/'
local palette = {
  N='263046', P='41405d', D='2f5a4b', G='4c8063', J='3fa88b',
  L='83b865', H='b4d67e', C='e8ddb6', W='f7f0d8', I='fdfbf2',
  A='c98b4a', Y='f1c86d', Z='fbe7a1',
}
local colors = {}
for k, hex in pairs(palette) do
  colors[k] = app.pixelColor.rgba(tonumber(hex:sub(1,2),16), tonumber(hex:sub(3,4),16), tonumber(hex:sub(5,6),16),255)
end
local function dot(img,x,y,col)
  if x>=0 and y>=0 and x<64 and y<64 then img:drawPixel(x,y,colors[col]) end
end
local function line(img,x0,y0,x1,y1,col)
  local dx,dy=math.abs(x1-x0),-math.abs(y1-y0)
  local sx,sy=x0<x1 and 1 or -1,y0<y1 and 1 or -1
  local err=dx+dy
  while true do
    dot(img,x0,y0,col)
    if x0==x1 and y0==y1 then break end
    local e=2*err
    if e>=dy then err=err+dy; x0=x0+sx end
    if e<=dx then err=err+dx; y0=y0+sy end
  end
end
local function rect(img,x,y,w,h,col)
  for yy=y,y+h-1 do for xx=x,x+w-1 do dot(img,xx,yy,col) end end
end
local function poly(img,points,col,outline)
  local minY,maxY=64,-1
  for _,p in ipairs(points) do minY=math.min(minY,p[2]);maxY=math.max(maxY,p[2]) end
  for y=minY,maxY do
    local cuts={}
    for i,p in ipairs(points) do
      local q=points[i % #points+1]
      if (p[2]<=y and q[2]>y) or (q[2]<=y and p[2]>y) then
        cuts[#cuts+1]=p[1]+(y-p[2])*(q[1]-p[1])/(q[2]-p[2])
      end
    end
    table.sort(cuts)
    for i=1,#cuts-1,2 do
      for x=math.ceil(cuts[i]),math.floor(cuts[i+1]) do dot(img,x,y,col) end
    end
  end
  if outline then
    for i,p in ipairs(points) do local q=points[i % #points+1];line(img,p[1],p[2],q[1],q[2],outline) end
  end
end
local function shift(points,dx,dy)
  local out={}
  for _,p in ipairs(points) do out[#out+1]={p[1]+dx,p[2]+dy} end
  return out
end
local layers={}
for i,name in ipairs({'Far feet and tail','Body and shell','Near feet','Head','Golden spirit seal'}) do
  local layer=i==1 and spr.layers[1] or spr:newLayer()
  layer.name=name;layers[i]=layer
end
for i=2,10 do spr:newEmptyFrame() end
local walkOffsets={-2,0,2,2,0,-2}
local oppositeOffsets={2,0,-2,-2,0,2}
local bodyBobs={0,-1,-1,0,-1,-1}
for frame=1,10 do
  local walking=frame>=5
  local k=walking and frame-4 or 1
  local bob=walking and bodyBobs[k] or (frame==2 and -1 or 0)
  local blink=not walking and frame==3
  local headY=not walking and (frame==4 and 1 or 0) or bob
  local leg1=walking and walkOffsets[k] or 0
  local leg2=walking and oppositeOffsets[k] or 0
  local lift1=walking and (k==2 or k==3) and -2 or 0
  local lift2=walking and (k==5 or k==6) and -2 or 0
  local tailY=(not walking and frame==4) and -1 or bob
  local imgs={}
  for i=1,5 do imgs[i]=Image(64,64,ColorMode.RGB) end
  local far,body,near,head,seal=table.unpack(imgs)
  -- Tiny pointed tail and the far pair of four compact legs.
  poly(far,shift({{14,41},{9,42},{11,45},{16,44}},0,tailY),'L','N')
  poly(far,shift({{20,40},{19,45},{21,48},{26,48},{26,46},{24,42}},leg2,-1),'G','N')
  poly(far,shift({{35,40},{35,46},{37,48},{42,48},{42,45},{40,41}},leg1,-1),'G','N')
  rect(far,21+leg2,46,3,1,'C');rect(far,37+leg1,46,3,1,'C')
  -- Cream belly below the thick jade shell rim.
  poly(body,shift({{16,36},{21,33},{38,33},{43,38},{40,45},{22,46},{16,43}},0,bob),'C','N')
  poly(body,shift({{20,41},{37,41},{40,43},{36,45},{23,44}},0,bob),'W',nil)
  -- Broad domed shell, high frontal view; large lit planes and restrained seams.
  poly(body,shift({{17,25},{22,22},{34,22},{41,26},{45,32},{44,38},{40,43},{21,43},{15,39},{13,33},{14,29}},0,bob),'D','N')
  poly(body,shift({{18,26},{23,23},{33,23},{39,26},{43,32},{42,37},{37,40},{22,40},{17,37},{15,32}},0,bob),'J',nil)
  poly(body,shift({{18,27},{23,24},{32,24},{30,27},{23,30},{17,30}},0,bob),'H',nil)
  poly(body,shift({{17,32},{23,31},{26,35},{23,39},{18,36}},0,bob),'L',nil)
  poly(body,shift({{26,29},{31,27},{37,30},{36,35},{29,37},{25,34}},0,bob),'L','G')
  poly(body,shift({{32,24},{38,27},{39,30},{34,28},{31,27}},0,bob),'J',nil)
  poly(body,shift({{38,30},{42,33},{41,37},{37,39},{36,35}},0,bob),'G',nil)
  line(body,23,30+bob,26,29+bob,'G')
  line(body,23,30+bob,23,25+bob,'G')
  line(body,23,39+bob,29,37+bob,'G')
  line(body,29,37+bob,30,40+bob,'G')
  line(body,16,38+bob,22,41+bob,'G')
  line(body,22,41+bob,36,41+bob,'G')
  line(body,37,41+bob,41,38+bob,'J')
  -- Near legs articulate independently; a lifted toe never slides the whole cel.
  poly(near,shift({{19,43},{18,48},{18,50},{21,52},{26,52},{27,50},{24,48},{24,43}},leg1,lift1),'L','N')
  poly(near,shift({{35,43},{34,47},{34,50},{37,52},{42,52},{43,50},{40,48},{40,43}},leg2,lift2),'L','N')
  rect(near,20+leg1,47+lift1,3,3,'H');rect(near,36+leg2,47+lift2,3,3,'H')
  rect(near,22+leg1,51+lift1,3,1,'W');rect(near,38+leg2,51+lift2,3,1,'W')
  dot(near,24+leg1,51+lift1,'N');dot(near,40+leg2,51+lift2,'N')
  -- Neck, rounded oversized face, small nose and cheek. Right-facing silhouette.
  poly(head,shift({{38,37},{43,35},{48,39},{48,44},{43,47},{39,44}},0,headY),'G','N')
  poly(head,shift({{43,30},{48,29},{53,31},{56,35},{56,40},{53,44},{45,45},{41,42},{40,36}},0,headY),'L','N')
  poly(head,shift({{42,33},{45,31},{50,31},{52,33},{47,34},{43,37},{42,40}},0,headY),'H',nil)
  poly(head,shift({{43,39},{48,37},{54,37},{55,39},{52,43},{46,44},{43,42}},0,headY),'W',nil)
  rect(head,44,35+headY,1,2,'G')
  if blink then
    line(head,48,36+headY,52,36+headY,'N')
  else
    rect(head,48,34+headY,4,4,'N')
    dot(head,48,34+headY,'I');dot(head,51,37+headY,'P')
  end
  dot(head,55,37+headY,'N')
  line(head,51,40+headY,53,40+headY,'G')
  rect(head,45,39+headY,2,1,'C')
  -- A single small golden forehead seal establishes the cultivation identity.
  poly(seal,shift({{46,30},{48,28},{50,30},{48,32}},0,headY),'Y','A')
  dot(seal,48,29+headY,'Z');dot(seal,48,30+headY,'Y')
  for i=1,5 do spr:newCel(layers[i],spr.frames[frame],imgs[i],Point(0,0)) end
  spr.frames[frame].duration=walking and 0.14 or (frame==3 and 0.13 or 0.38)
end
local idle=spr:newTag(spr.frames[1],spr.frames[4]);idle.name='idle'
local walk=spr:newTag(spr.frames[5],spr.frames[10]);walk.name='walk'
spr:saveAs(root..'spirit-turtle.aseprite')
print('OK: 64x64, 10 frames, 5 editable layers, idle 1-4, walk 5-10, ground y52')
